import{_ as i,C as c,o as t,c as d,a2 as a,b as l,w as o,a as s,E as n,a3 as u}from"./chunks/framework.DZUUNQ77.js";const P=JSON.parse('{"title":"StubCP · 占位 ContentProvider","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/stub-cp.md","filePath":"reference/client/stub-cp.md","lastUpdated":1784063681000}'),h={name:"reference/client/stub-cp.md"};function p(b,e,C,E,A,v){const r=c("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="stubcp-·-占位-contentprovider" tabindex="-1">StubCP · 占位 ContentProvider <a class="header-anchor" href="#stubcp-·-占位-contentprovider" aria-label="Permalink to &quot;StubCP · 占位 ContentProvider&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/stub/StubCP.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/stub/StubCP.java</code></a></p></div><p><code>StubCP</code> 是客户端侧的占位 ContentProvider，和 server 端的 <a href="./../server/ipc"><code>BinderProvider</code></a> 配对。它在宿主 Manifest 里声明（<code>C0</code>~<code>CN</code> 多个实例），是 server <strong>反向调用 client</strong> 的入口通道。</p><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p>VirtualXposed 的 IPC 主通道是 client → server（client 取服务 binder）。但有时 server 要主动通知 client（如角标更新、广播投递），需要反向通道。<code>StubCP</code> 就是这个反向入口：server 通过 <code>ContentResolver.call</code> 调用 client 侧的 <code>StubCP.call(method)</code>，触发 client 端逻辑。</p><h2 id="call-方法" tabindex="-1">call 方法 <a class="header-anchor" href="#call-方法" aria-label="Permalink to &quot;call 方法&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Bundle </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(String method, String arg, Bundle extras)</span></span></code></pre></div><p>按 <code>method</code> 名分发到不同的 client 端处理逻辑（角标、广播等）。其他 CRUD 方法（<code>query</code>/<code>insert</code>/<code>update</code>/<code>delete</code>）一般空实现，因为它只做 <code>call</code> 通道。</p><h2 id="反向-ipc-通道" tabindex="-1">反向 IPC 通道 <a class="header-anchor" href="#反向-ipc-通道" aria-label="Permalink to &quot;反向 IPC 通道&quot;">​</a></h2>',9)),(t(),l(u,null,{default:o(()=>[n(r,{id:"mermaid-27",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRV%5B%22server%20%E4%B8%BB%E5%8A%A8%E9%80%9A%E7%9F%A5%22%5D%20--%3E%20CR%5B%22ContentResolver.call%22%5D%0A%20%20CR%20--%3E%20SCP%5B%22StubCP.call(method)%22%5D%0A%20%20SCP%20--%3E%7C%22%E6%8C%89%20method%20%E5%88%86%E5%8F%91%22%7C%20HANDL%5B%22client%20%E7%AB%AF%E5%A4%84%E7%90%86%3Cbr%2F%3E(%E8%A7%92%E6%A0%87%2F%E5%B9%BF%E6%92%AD%E7%AD%89)%22%5D%0A%20%20HANDL%20--%3E%20APP%5B%22%E8%99%9A%E6%8B%9F%20App%22%5D%0A%20%20SCP%20-.-%3E%7C%22C0~CN%20%E5%A4%9A%E5%AE%9E%E4%BE%8B%3Cbr%2F%3E%E7%8B%AC%E7%AB%8B%20authority%22%7C%20MULT%5B%22%E9%81%BF%E5%85%8D%E7%94%A8%E6%88%B7%2F%E5%8C%85%E5%86%B2%E7%AA%81%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="多实例-c0-cn" tabindex="-1">多实例 C0~CN <a class="header-anchor" href="#多实例-c0-cn" aria-label="Permalink to &quot;多实例 C0~CN&quot;">​</a></h2><p>和 StubActivity 一样，<code>StubCP</code> 也有 <code>C0</code>~<code>CN</code> 多个子类实例，每个有独立 authority（<code>virtual_stub_N</code>），对应不同虚拟用户/包，避免冲突。</p><h2 id="vasettings-关联" tabindex="-1">VASettings 关联 <a class="header-anchor" href="#vasettings-关联" aria-label="Permalink to &quot;VASettings 关联&quot;">​</a></h2><p><code>VASettings.STUB_DEF_AUTHORITY = &quot;virtual_stub_&quot;</code> 是 authority 前缀，<code>getStubAuthority(index)</code> / <code>getStubCP(index)</code> 按索引生成对应类名和 authority。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../server/ipc"><code>BinderProvider</code></a>：正向通道（client→server）。</li><li><a href="./../remote/badger-info"><code>BadgerInfo</code></a>：角标反向通知的载荷。</li><li><a href="./va-settings"><code>VASettings</code></a>：authority 配置。</li><li><a href="./../../features/ipc-bridge">IPC 桥</a>。</li></ul>',6))])}const _=i(h,[["render",p]]);export{P as __pageData,_ as default};
